/**
 * Storage adapter interface — the persistence boundary for the whole app.
 *
 * Every feature reads and writes through `StorageAdapter`. No feature module
 * may import `localStorage` or `@supabase/supabase-js` directly. Backend
 * selection happens once, in `getBackend()`, and is invisible to callers.
 *
 * Contract notes that both backends honour:
 *  - IDs are opaque strings generated by the backend, never by callers.
 *  - `Timestamps` are ISO-8601 UTC strings.
 *  - Reads never throw for "not found"; they return `null` or `[]`.
 *  - Mutations validate their input with the schemas in `validation.ts` and
 *    throw `StorageError` on rejection.
 *  - The user is fixed per session: `getUser()` resolves the current user, or
 *    `null` when unauthenticated. User-scoped methods reject when it is null.
 */
import type {
  Exercise,
  ExerciseLog,
  FitnessLevel,
  OnboardingAnswers,
  PrimaryGoal,
  Profile,
  WorkoutDay,
  WorkoutDayWithExercises,
  WorkoutExercise,
  WorkoutLog,
  WorkoutLogWithExercises,
  WorkoutPlan,
  WorkoutPlanWithDays,
} from '@/lib/domain/types';
import type { PlanDraftInput } from '@/lib/domain/validation';

export type BackendKind = 'local' | 'supabase';

/** Thrown for expected, user-recoverable persistence failures. */
export class StorageError extends Error {
  readonly code: StorageErrorCode;

  constructor(code: StorageErrorCode, message: string) {
    super(message);
    this.name = 'StorageError';
    this.code = code;
  }
}

export type StorageErrorCode =
  | 'unauthenticated'
  | 'not_found'
  | 'validation_failed'
  | 'conflict'
  | 'unavailable';

export type AuthUser = {
  id: string;
  email: string;
  /** Null in local mode — local users have no email. */
  emailVerified: boolean | null;
};

/** Signed-up landing page email captures. Local-only, never synced. */
export type EmailSignup = {
  id: string;
  email: string;
  createdAt: string;
};

export type AuthCredentials = {
  email: string;
  password: string;
};

export type AuthResult = { user: AuthUser } | { error: StorageError };

/** Filters accepted by `listExercises`. All fields are optional. */
export type ExerciseQuery = {
  search?: string;
  bodyParts?: readonly string[];
  muscles?: readonly string[];
  difficulty?: readonly FitnessLevel[];
  types?: readonly string[];
  /**
   * Duration buckets for time-based movements. Rep-based movements are
   * excluded by every bucket rather than being folded in, because "under 30s"
   * is not meaningful for a movement prescribed in reps.
   */
  durationBuckets?: readonly DurationBucket[];
  limit?: number;
  offset?: number;
};

/** Coarse duration bands, in ascending order of length. */
export const DURATION_BUCKETS = ['quick', 'standard', 'long'] as const;
export type DurationBucket = (typeof DURATION_BUCKETS)[number];

/** Which duration bucket a movement belongs to, or `null` when rep-based. */
export const durationBucketOf = (exercise: {
  recommendedDurationSeconds: number | null;
  exerciseType: string;
}): DurationBucket | null => {
  const seconds = exercise.recommendedDurationSeconds;
  if (seconds === null) return null;
  if (seconds <= 20) return 'quick';
  if (seconds <= 45) return 'standard';
  return 'long';
};

export type AuthAdapter = {
  /** Current user, or null when signed out. Never throws. */
  getUser(): Promise<AuthUser | null>;
  /** Emits on sign-in/sign-out. Returns an unsubscribe function. */
  onAuthStateChange(
    callback: (user: AuthUser | null) => void,
  ): () => void;
  signUp(
    credentials: AuthCredentials,
  ): Promise<{ user: AuthUser; needsEmailConfirmation: boolean } | { error: StorageError }>;
  signIn(credentials: AuthCredentials): Promise<AuthResult>;
  signOut(): Promise<{ error: StorageError | null }>;
  requestPasswordReset(email: string): Promise<{ error: StorageError | null }>;
  /**
   * Sets a new password for the signed-in user. Only valid while a recovery
   * session from an emailed reset link is active. Local mode returns
   * `unavailable`.
   */
  updatePassword(password: string): Promise<{ error: StorageError | null }>;
  /** Supabase only; local mode returns an `unavailable` error. */
  signInWithGoogle(): Promise<AuthResult>;
};

export type ProfileAdapter = {
  get(): Promise<Profile | null>;
  save(answers: OnboardingAnswers): Promise<Profile>;
  update(changes: Partial<Omit<Profile, 'id' | 'createdAt'>>): Promise<Profile>;
  /** Marks onboarding finished. Idempotent. */
  completeOnboarding(): Promise<Profile>;
};

export type ExerciseCatalogAdapter = {
  list(query?: ExerciseQuery): Promise<Exercise[]>;
  getById(id: string): Promise<Exercise | null>;
  getBySlug(slug: string): Promise<Exercise | null>;
  count(query?: ExerciseQuery): Promise<number>;
};

export type WorkoutPlanAdapter = {
  getActive(): Promise<WorkoutPlanWithDays | null>;
  getById(id: string): Promise<WorkoutPlanWithDays | null>;
  list(): Promise<WorkoutPlan[]>;
  /**
   * Creates or replaces a plan together with its days and exercises, and makes
   * it the active plan. Re-saving the same `id` replaces its day graph.
   * Declared from the Zod schema so the shape cannot drift from validation.
   */
  save(draft: PlanDraftInput): Promise<WorkoutPlanWithDays>;
  /** Deletes a plan and its days/exercises. */
  remove(id: string): Promise<void>;
  getDayWithExercises(id: string): Promise<WorkoutDayWithExercises | null>;
};

export type WorkoutLogAdapter = {
  /** Logs a completed session plus its exercise entries atomically. */
  start(input: {
    workoutPlanId: string | null;
    workoutDayId: string | null;
    startedAt: string;
  }): Promise<WorkoutLog>;
  complete(
    id: string,
    input: { completedAt: string; durationSeconds: number; notes?: string },
  ): Promise<WorkoutLog>;
  abandon(id: string): Promise<void>;
  logExercise(
    input: Omit<ExerciseLog, 'id' | 'workoutLogId' | 'createdAt'>,
    workoutLogId: string,
  ): Promise<ExerciseLog>;
  getById(id: string): Promise<WorkoutLogWithExercises | null>;
  listRecent(limit?: number): Promise<WorkoutLog[]>;
};

export type SignupCaptureAdapter = {
  capture(email: string): Promise<EmailSignup>;
  list(): Promise<EmailSignup[]>;
};

/** The single interface all app code depends on. */
export type StorageAdapter = {
  readonly kind: BackendKind;
  /** True when Supabase env vars were present at startup. */
  readonly cloudConfigured: boolean;
  auth: AuthAdapter;
  profiles: ProfileAdapter;
  exercises: ExerciseCatalogAdapter;
  plans: WorkoutPlanAdapter;
  logs: WorkoutLogAdapter;
  signups: SignupCaptureAdapter;
};

// --- Re-exported for adapter authors ---------------------------------------
export type {
  Exercise,
  ExerciseLog,
  OnboardingAnswers,
  PrimaryGoal,
  Profile,
  WorkoutDay,
  WorkoutDayWithExercises,
  WorkoutExercise,
  WorkoutLog,
  WorkoutLogWithExercises,
  WorkoutPlan,
  WorkoutPlanWithDays,
};
export type { PlanDraftInput };
